'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm'),path=require('node:path');
const root=path.resolve(__dirname,'..'),ctx={console,Intl,Date,Math,Set,Map,Object,Array,Number,JSON};ctx.globalThis=ctx;vm.createContext(ctx);
for(const f of ['vendor/astronomy-engine-2.1.19.min.js','vedic-ayanamsa.js','astro-time.js','western-engine.js','western-prompt.js','western-chart.js'])vm.runInContext(fs.readFileSync(path.join(root,'JS',f),'utf8'),ctx);
const E=ctx.JYWestern,T=ctx.JYAstroTime,fixture=require('./fixtures/western-swiss-20260914.json'),ms=jd=>(jd-2440587.5)*86400000;
let passed=0;function test(name,fn){fn();passed++;console.log('PASS '+name);}
const maximum={longitude:0,latitude:0,speed:0,node:0,angles:0,cusps:0,returnMinutes:0};
test('167 independent Swiss/Moshier references: ten planets, lunar node, four house systems',()=>{for(const c of fixture.cases){const date=new Date(ms(c.jd)),ps=E.planets(date);for(const [k,r]of Object.entries(c.planets)){const lon=Math.abs(E.diff(ps[k].longitude,r[0]))*3600,lat=Math.abs(ps[k].latitude-r[1])*3600,speed=Math.abs(ps[k].speed-r[2])*3600;maximum.longitude=Math.max(maximum.longitude,lon);maximum.latitude=Math.max(maximum.latitude,lat);maximum.speed=Math.max(maximum.speed,speed);assert(lon<60,k+' longitude');assert(lat<60,k+' latitude');assert(speed<4,k+' speed');if(Math.abs(r[2])>.002)assert.equal(ps[k].retrograde,r[2]<0);}maximum.node=Math.max(maximum.node,Math.abs(E.diff(ps.NorthNode.longitude,c.node))*3600);assert(Math.abs(E.norm(ps.SouthNode.longitude-ps.NorthNode.longitude)-180)<1e-9);for(const [system,r]of Object.entries(c.houses)){if(r.error){assert.throws(()=>E.houses(date,c.latitude,c.longitude,system),/Placidus/);continue;}const h=E.houses(date,c.latitude,c.longitude,system);maximum.angles=Math.max(maximum.angles,Math.abs(E.diff(h.angles.ASC,r.asc))*3600,Math.abs(E.diff(h.angles.MC,r.mc))*3600);let sum=0;h.cusps.forEach((n,i)=>{const gap=Math.abs(E.diff(n,r.cusps[i]))*3600;maximum.cusps=Math.max(maximum.cusps,gap);assert(gap<60,system+' cusp '+i);assert.equal(E.houseOf(n,h.cusps),i+1);sum+=E.norm(h.cusps[(i+1)%12]-n);});assert(Math.abs(sum-360)<1e-7);}}});
test('DST gap, fold and civil dates preserve the actual UTC instant',()=>{assert.throws(()=>T.civilToUTC({date:'2024-03-10',time:'02:30',timezone:'America/New_York'}),/不存在/);assert.throws(()=>T.civilToUTC({date:'2024-11-03',time:'01:30',timezone:'America/New_York'}),/兩次/);const c={date:'2024-11-03',time:'01:30',timezone:'America/New_York'};assert.equal(+T.civilToUTC({...c,disambiguation:'later'}).date-+T.civilToUTC({...c,disambiguation:'earlier'}).date,3600000);assert.throws(()=>T.civilToUTC({date:'2026-02-29',time:'10:00',timezone:'Asia/Taipei'}),/不存在/);assert.equal(T.civilToUTC({date:'1983-08-25',time:'14:55',timezone:'Asia/Taipei'}).date.toISOString(),'1983-08-25T06:55:00.000Z');});
test('Unknown clock covers a 23/25-hour day and midnight DST transitions',()=>{for(const [date,zone,hours]of [['2024-03-10','America/New_York',23],['2024-11-03','America/New_York',25],['2018-11-04','America/Sao_Paulo',23]]){const bounds=T.civilDayBounds(date,zone);assert.equal((bounds[1]-bounds[0])/3600000,hours);}assert.throws(()=>T.civilDayBounds('2011-12-30','Pacific/Apia'),/不存在/);});
const make=(key,lon,speed)=>({key,longitude:lon,speed,sign:Math.floor(lon/30)});
test('Applying/separating handles retrograde, zero crossing, opposition and exactness',()=>{assert.equal(E.pairAspect(make('Mars',359,1),make('Jupiter',1,.1)).phase,'入相');assert.equal(E.pairAspect(make('Mars',359,-1),make('Jupiter',1,.1)).phase,'出相');assert.equal(E.pairAspect(make('Mars',0,0),make('Jupiter',179,1)).phase,'入相');assert.equal(E.pairAspect(make('Mars',0,0),make('Jupiter',181,1)).phase,'出相');assert.equal(E.pairAspect(make('Mars',0,0),make('Jupiter',180,-1)).phase,'精確');assert.equal(E.pairAspect(make('Mars',0,0),make('Jupiter',70,0)),null);});
test('Classical dignities distinguish Mercury domicile plus exaltation and outer planets',()=>{assert.equal(E.dignity('Mercury',5).name,'入廟・擢升');assert.equal(E.dignity('Venus',5).name,'落陷');assert.equal(E.dignity('Mars',6).name,'失勢');assert.equal(E.dignity('Uranus',10).states.length,0);});
test('Grand trine, T-square and grand cross require every actual link',()=>{const a=(a,b,angle)=>({a,b,angle});const base=[a('Sun','Moon',180),a('Mars','Sun',90),a('Mars','Moon',90)];assert.equal(E.patterns(base).find(x=>x.name==='T 三角').apex,'Mars');assert.equal(E.patterns(base.slice(0,2)).length,0);assert.equal(E.patterns([a('Sun','Moon',120),a('Sun','Jupiter',120),a('Moon','Jupiter',120)])[0].name,'大三角');const cross=base.concat(a('Jupiter','Sun',90),a('Jupiter','Moon',90),a('Jupiter','Mars',180));assert(E.patterns(cross).some(x=>x.name==='大十字'));});
test('Solar returns and secondary progression use independent Swiss timing references',()=>{for(const c of fixture.timing){const chart=E.compute({utc:new Date(ms(c.birthJD)),reference:new Date(ms(c.referenceJD)),latitude:25.03,longitude:121.56,houseSystem:'P'});const minutes=Math.abs(+new Date(chart.solarReturn.utc)-ms(c.returnJD))/60000;maximum.returnMinutes=Math.max(maximum.returnMinutes,minutes);assert(minutes<3,'solar return');assert(Math.abs(+new Date(chart.progressions.utc)-ms(c.progressJD))<2,'progressed instant');for(const k of E.KEYS)assert(Math.abs(E.diff(chart.progressions.planets[k].longitude,c.progressed[k]))<1/60);assert(chart.solarReturn.residualDegrees<1e-7);assert(Object.isFrozen(chart.planets.Sun));}});
const sample=E.compute({utc:'1983-08-25T06:55:00Z',reference:'2026-09-14T04:00:00Z',latitude:25.03,longitude:121.56,houseSystem:'P',civil:{date:'1983-08-25',time:'14:55',timezone:'Asia/Taipei'}});
test('Every displayed planet house matches the same snapshot; angles stay distinct from equal cusps',()=>{for(const p of Object.values(sample.planets))assert.equal(p.house,E.houseOf(p.longitude,sample.houses.cusps));const h=E.houses('1983-08-25T06:55:00Z',25.03,121.56,'E');assert(Math.abs(E.diff(h.angles.MC,h.cusps[9]))>1);assert(sample.transits.aspects.every(a=>a.kind==='行運對本命'));assert.equal(sample.progressions.planets.Sun.house,null);});
test('Unknown time has no houses, ruler, sect, progression or solar return',()=>{const c=E.compute({utc:'1983-08-25T04:00:00Z',reference:'2026-09-14T04:00:00Z',latitude:25.03,longitude:121.56,unknownTime:true,civil:{date:'1983-08-25',time:'12:00',timezone:'Asia/Taipei'}});for(const k of ['houses','chartRuler','sect','progressions','solarReturn'])assert.equal(c[k],null);assert(c.sensitivity.planets.find(p=>p.key==='Moon').spanDegrees>10);assert(c.aspects.every(a=>a.kind!=='角點'));const prompt=ctx.JYWesternPrompt.build(c);assert(prompt.includes('當地中午參考值'));assert(!ctx.JYWesternChart.wheel(c).includes('data-wx-house'));});
test('Every topic retains the actual question, chart sources and one shop link',()=>{for(const topic of Object.keys(ctx.JYWesternPrompt.TOPICS)){const text=ctx.JYWesternPrompt.build(sample,{topic,question:'如何安排轉職與收入？'});assert(text.includes('如何安排轉職與收入？'));assert(text.includes('回歸黃道'));assert(text.includes('相位'));assert(text.includes(sample.input.utc));assert.equal(text.split('https://shopee.tw/').length-1,1);assert(text.includes('下一步'));}});
test('Legacy ephemeris bridge never leaves stale derived fields after partial overwrite',()=>{let calls=0;const c={window:{},fetch:()=>{calls++;throw Error('no partial API patch');}};vm.createContext(c);vm.runInContext(fs.readFileSync(path.join(root,'JS/ephemeris-client.js'),'utf8'),c);const native={planets:{太陽:{lon:20}},aspects:[{orb:2}]};c.window._JY_EPHEMERIS.upgradeNatal(native).then(out=>assert.equal(out,native));assert.equal(calls,0);});
console.log(JSON.stringify({passed,referenceCases:fixture.cases.length,maximum},null,2));
